insert into public.products (id, name, conc, gender, family, tagline, description, notes, longevity, sillage, seasons, times, sizes, sample, look, badge, rank, added, stock, images) values ('rasa', 'Rasa', 'EDP', 'moterims', 'geliu', 'Ryto gaiva ant baltųjų rožių', 'Lengvas, švarus gėlių kvapas, kuris primena ankstyvą vasaros rytą sode: rasotos rožės, žalia kriaušė ir minkštas baltas muskusas.', '{"top":["Kriaušė","Bergamotė"],"heart":["Baltoji rožė","Bijūnas"],"base":["Baltasis muskusas","Kašmyro mediena"]}'::jsonb, 3, 2, array['pavasaris','vasara']::text[], array['diena']::text[], '[{"ml":30,"price":45},{"ml":50,"price":65},{"ml":100,"price":95}]'::jsonb, 4.9, '{"liquid":"#F6C6CF","tint":"#FCEFF2","cap":"gold","shape":"rect"}'::jsonb, 'Populiaru', 1, '2026-03-01', null, '{}'::text[]) on conflict (id) do nothing;
